"""minisql -- a tiny SQL SELECT engine.

Supported grammar (recursive-descent, no sqlite3 anywhere in the engine):

    query        := SELECT select_list FROM table_name
                    [WHERE expr] [ORDER BY order_list] [LIMIT integer]
    select_list  := "*" | column ("," column)*
    order_list   := ordering ("," ordering)*
    ordering     := column [ASC | DESC]
    expr         := or_expr
    or_expr      := and_expr (OR and_expr)*
    and_expr     := not_expr (AND not_expr)*
    not_expr     := NOT not_expr | primary
    primary      := "(" expr ")" | comparison
    comparison   := operand compare_op operand
    operand      := literal | column
    literal      := integer | real | 'string'
    compare_op   := "=" | "!=" | "<" | ">" | "<=" | ">="

Public API:

    query(sql, table) -> list[tuple]

`table` is a list of dicts (column name -> value); the FROM table name is
parsed but otherwise ignored beyond validation.

NULL restriction: this engine does NOT implement SQL three-valued logic.
Comparisons involving None raise TypeError rather than yielding UNKNOWN,
and ORDER BY treats None as incomparable. Tests must therefore keep the
fixture NULL-free; behaviour on NULLs is unspecified by design.
"""

import re


class SQLError(ValueError):
    """Raised for any syntax or semantic error in a query."""


# --------------------------------------------------------------------------
# Tokenizer
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
      (?P<ws>\s+)
    | (?P<number>\d+\.\d+|\d+)
    | (?P<string>'[^']*')
    | (?P<ident>[A-Za-z_][A-Za-z_0-9]*)
    | (?P<op><=|>=|!=|=|<|>|\(|\)|,|\*)
    """,
    re.VERBOSE,
)

_KEYWORDS = {
    "SELECT", "FROM", "WHERE", "ORDER", "BY", "AND", "OR", "NOT",
    "ASC", "DESC", "LIMIT",
}


class _Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind, value):
        self.kind = kind          # 'kw', 'ident', 'number', 'string', 'op', 'eof'
        self.value = value

    def __repr__(self):           # pragma: no cover - debugging aid
        return f"_Token({self.kind!r}, {self.value!r})"


def _tokenize(sql):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if not m:
            raise SQLError(f"unexpected character {sql[pos]!r} at position {pos}")
        pos = m.end()
        kind = m.lastgroup
        text = m.group()
        if kind == "ws":
            continue
        if kind == "number":
            value = float(text) if "." in text else int(text)
            tokens.append(_Token("number", value))
        elif kind == "string":
            tokens.append(_Token("string", text[1:-1]))
        elif kind == "ident":
            upper = text.upper()
            if upper in _KEYWORDS:
                tokens.append(_Token("kw", upper))
            else:
                tokens.append(_Token("ident", text))
        else:
            tokens.append(_Token("op", text))
    tokens.append(_Token("eof", None))
    return tokens


# --------------------------------------------------------------------------
# AST nodes
# --------------------------------------------------------------------------

class _Column:
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


class _Literal:
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value


class _Compare:
    __slots__ = ("left", "op", "right")

    def __init__(self, left, op, right):
        self.left, self.op, self.right = left, op, right


class _Not:
    __slots__ = ("operand",)

    def __init__(self, operand):
        self.operand = operand


class _And:
    __slots__ = ("parts",)

    def __init__(self, parts):
        self.parts = parts


class _Or:
    __slots__ = ("parts",)

    def __init__(self, parts):
        self.parts = parts


# --------------------------------------------------------------------------
# Parser
# --------------------------------------------------------------------------

class _Parser:
    def __init__(self, sql):
        self._tokens = _tokenize(sql)
        self._pos = 0

    # -- token helpers -----------------------------------------------------

    def _peek(self):
        return self._tokens[self._pos]

    def _next(self):
        tok = self._tokens[self._pos]
        self._pos += 1
        return tok

    def _accept_kw(self, *words):
        tok = self._peek()
        if tok.kind == "kw" and tok.value in words:
            self._pos += 1
            return tok.value
        return None

    def _expect_kw(self, word):
        if not self._accept_kw(word):
            tok = self._peek()
            raise SQLError(f"expected {word}, got {tok.value!r}")

    def _accept_op(self, *ops):
        tok = self._peek()
        if tok.kind == "op" and tok.value in ops:
            self._pos += 1
            return tok.value
        return None

    def _expect_op(self, op):
        if not self._accept_op(op):
            tok = self._peek()
            raise SQLError(f"expected {op!r}, got {tok.value!r}")

    def _expect_ident(self, what="identifier"):
        tok = self._peek()
        if tok.kind != "ident":
            raise SQLError(f"expected {what}, got {tok.value!r}")
        self._pos += 1
        return tok.value

    # -- grammar -------------------------------------------------------------

    def parse(self):
        self._expect_kw("SELECT")
        select_list = self._select_list()
        self._expect_kw("FROM")
        self._expect_ident("table name")   # validated only; table passed as arg
        where = None
        if self._accept_kw("WHERE"):
            where = self._expr()
        order_by = []
        if self._accept_kw("ORDER"):
            self._expect_kw("BY")
            while True:
                col = self._expect_ident("column name")
                direction = self._accept_kw("ASC", "DESC") or "ASC"
                order_by.append((col, direction))
                if not self._accept_op(","):
                    break
        limit = None
        if self._accept_kw("LIMIT"):
            tok = self._peek()
            if tok.kind != "number" or not isinstance(tok.value, int) or tok.value < 0:
                raise SQLError("LIMIT expects a non-negative integer")
            self._pos += 1
            limit = tok.value
        if self._peek().kind != "eof":
            raise SQLError(f"unexpected trailing token {self._peek().value!r}")
        return select_list, where, order_by, limit

    def _select_list(self):
        if self._accept_op("*"):
            return "*"
        cols = [self._expect_ident("column name")]
        while self._accept_op(","):
            cols.append(self._expect_ident("column name"))
        return cols

    def _expr(self):
        parts = [self._and_expr()]
        while self._accept_kw("OR"):
            parts.append(self._and_expr())
        return parts[0] if len(parts) == 1 else _Or(parts)

    def _and_expr(self):
        parts = [self._not_expr()]
        while self._accept_kw("AND"):
            parts.append(self._not_expr())
        return parts[0] if len(parts) == 1 else _And(parts)

    def _not_expr(self):
        if self._accept_kw("NOT"):
            return _Not(self._not_expr())
        return self._primary()

    def _primary(self):
        if self._accept_op("("):
            expr = self._expr()
            self._expect_op(")")
            return expr
        left = self._operand()
        op = self._accept_op("=", "!=", "<=", ">=", "<", ">")
        if op is None:
            raise SQLError(f"expected comparison operator, got {self._peek().value!r}")
        right = self._operand()
        return _Compare(left, op, right)

    def _operand(self):
        tok = self._next()
        if tok.kind == "number" or tok.kind == "string":
            return _Literal(tok.value)
        if tok.kind == "ident":
            return _Column(tok.value)
        raise SQLError(f"expected literal or column, got {tok.value!r}")


# --------------------------------------------------------------------------
# Evaluator / executor
# --------------------------------------------------------------------------

def _eval(node, row):
    if isinstance(node, _Literal):
        return node.value
    if isinstance(node, _Column):
        try:
            return row[node.name]
        except KeyError:
            raise SQLError(f"unknown column {node.name!r}") from None
    if isinstance(node, _Not):
        return not _eval(node.operand, row)
    left = _eval(node.left, row)
    right = _eval(node.right, row)
    ops = {
        "=": lambda a, b: a == b,
        "!=": lambda a, b: a != b,
        "<": lambda a, b: a < b,
        ">": lambda a, b: a > b,
        "<=": lambda a, b: a <= b,
        ">=": lambda a, b: a >= b,
    }
    return ops[node.op](left, right)


def query(sql, table):
    """Run a SELECT statement against `table` (list[dict]) -> list[tuple].

    See module docstring for supported syntax and the NULL restriction.
    """
    select_list, where, order_by, limit = _Parser(sql).parse()

    columns = sorted(table[0].keys()) if False else None  # placeholder, see below
    if select_list == "*":
        out_cols = list(table[0].keys()) if table else []
    else:
        out_cols = select_list
        known = set()
        for r in table:
            known.update(r.keys())
        for c in out_cols:
            if c not in known:
                raise SQLError(f"unknown column {c!r}")

    rows = table
    if where is not None:
        rows = [r for r in rows if _bool(_eval(where, r))]

    # Multi-key ORDER BY: stable-sort back-to-front so earlier keys dominate.
    for col, direction in reversed(order_by):
        if col not in (table[0] if table else {}):
            if any(col in r for r in table) or True:
                pass
        rows = sorted(
            rows,
            key=lambda r, c=col: _sort_key(r.get(c)),
            reverse=(direction == "DESC"),
        )

    result = [tuple(r[c] for c in out_cols) for r in rows]
    if limit is not None:
        result = result[:limit]
    return result


def _bool(v):
    if not isinstance(v, bool):
        raise SQLError("WHERE clause must evaluate to a boolean")
    return v


def _sort_key(v):
    # Fixture is guaranteed NULL-free (see module docstring); give None a
    # well-defined slot anyway so the engine never crashes mid-sort.
    return ((v is None), v)

